export type WebhookTestResponse = {
  /**
   * Whether your endpoint accepted the test event. `delivered` means it returned a `2xx` status; `failed` means it returned a non-`2xx` status or could not be reached (see `error` for the latter).
   *
   */
  status: "delivered" | "failed";
  /**
   * HTTP status returned by your endpoint. Null when no response was received (timeout, connection error, DNS failure).
   */
  response_status_code: number | null;
  /**
   * Response body returned by your endpoint, truncated to the first 1024 bytes. Omitted when your endpoint returned no body or could not be reached.
   *
   */
  response_body?: string;
  /**
   * Round-trip delivery latency in milliseconds.
   */
  response_duration_ms: number;
  /**
   * The full event body delivered to your endpoint. Test sends use a minimal synthetic body rather than a full event payload, so this field is omitted.
   *
   */
  event_payload?: WebhookEvent;
  /**
   * A short explanation of why the event could not be delivered. Present only when your endpoint could not be reached.
   */
  error?: string;
};

export type WebhookReplayRequest = {
  /**
   * Replay events that occurred at or after this timestamp. Defaults to 24 hours before the request when omitted.
   *
   */
  since?: string;
  /**
   * Replay events that occurred before or at this timestamp. Omit to bound the window only by `since`.
   *
   */
  until?: string;
};

export type WebhookEventId = string;

export type WebhookAttempt = {
  /**
   * Identifier of this individual delivery attempt. Each retry is a separate attempt with its own id; use `event_id` to group the attempts for one event.
   *
   */
  readonly id: string;
  /**
   * Bird's source event ID, stable across retries of the same event. Null only for older attempts recorded before event IDs were available.
   */
  event_id?: WebhookEventId | null;
  event_type: WebhookEventType;
  /**
   * Outcome of this attempt.
   *
   * - `delivered`: your endpoint accepted it with a `2xx` response.
   * - `pending`: the attempt is still in flight.
   * - `failed`: it returned a non-`2xx` response or no response at all. A `failed`
   * attempt is not final for the event: automatic retries appear as further
   * attempts with the same `event_id`.
   *
   */
  status: "delivered" | "pending" | "failed";
  /**
   * URL the request was sent to: the endpoint's `url` at the time of the attempt, which can differ from the current configuration after an update.
   *
   */
  url: string;
  /**
   * HTTP status returned by the receiver. Null when no response was received (timeout, connection error, DNS failure).
   */
  response_status_code: number | null;
  /**
   * Response body your endpoint returned, which may be truncated. Omitted when no body was returned.
   *
   */
  response_body?: string;
  /**
   * Round-trip duration in milliseconds.
   */
  response_duration_ms: number;
  /**
   * When this attempt was made. Attempts are listed newest first by this timestamp, and the list's `before`/`after` parameters bound it.
   *
   */
  readonly attempted_at: string;
};

export type WebhookAttemptList = {
  /**
   * Delivery attempts, newest first.
   */
  data: Array<WebhookAttempt>;
};

/**
 * Physical type of a phone number. New number types may be added over time, so treat unrecognized values as supported types rather than errors.
 */
export type NumberType =
  | "mobile"
  | "local"
  | "national"
  | "short_code"
  | "short_code_fteu"
  | "toll_free"
  | (string & {});

/**
 * A capability supported by a phone number. New capabilities may be added over time, so treat unrecognized values as supported capabilities rather than errors.
 */
export type NumberCapability = "sms" | "mms" | "voice" | (string & {});

/**
 * Where this number stands with the ownership paperwork its country requires before it may carry traffic. Present only for a number whose country requires any, so its absence means no paperwork was ever asked for and this number is unconditionally usable. Absent as well when the requirement cannot be established right now, since reporting either answer would state something about your paperwork that has not been checked.
 *
 */
export type NumberOwnership = {
  /**
   * Whether the paperwork is accepted. Read `next` for what advances it while this is false. Whether sending is currently refused is reported by `blocked_at` instead: a number bought before its country asked for anything is unsatisfied and still usable until a review says otherwise.
   *
   */
  readonly satisfied: boolean;
  /**
   * When the number stopped being able to carry traffic, and null while it can. Always null when `satisfied` is true, but null does not imply it: a number whose country began asking after you bought it is usable with its paperwork still outstanding. A number can also arrive blocked, and one that was usable can be blocked again if its approval is withdrawn.
   *
   */
  readonly blocked_at?: string | null;
  /**
   * What you do about it, in the order to do it. Empty only when `satisfied` is true, so while anything is outstanding there is always at least one step. When what you already sent is being reviewed and nothing is needed from you, that step has kind `wait` and says so. Re-read it after each call rather than caching the first list you saw.
   *
   */
  readonly next: Array<NextAction>;
};

export type Number = {
  /**
   * Identifier of this allocated number. Pass it as `number_id` to read this number, or to release it when kind is dedicated.
   */
  readonly id: AllocatedNumberId;
  /**
   * How this number is allocated. `dedicated` belongs to your workspace and is billed as a subscription. `shared` is provided through Bird-managed shared infrastructure and is not owned or billed as a workspace subscription.
   */
  readonly kind: "dedicated" | "shared";
  /**
   * Phone number in E.164 format.
   */
  readonly number: string;
  readonly country_code: CountryCode;
  /**
   * Physical type of this phone number.
   */
  readonly number_type: NumberType;
  /**
   * Capabilities supported by this number.
   */
  readonly capabilities: Array<NumberCapability>;
  /**
   * The allocation and ownership-approval status of this number.
   *
   * - `active` means this number is allocated to your workspace and usable.
   * - `pending_ownership_registration` means this number is allocated to your workspace and billed,
   * but outbound SMS and both inbound and outbound voice calls are blocked until the ownership paperwork
   * its country requires is accepted. This ownership status does not gate inbound SMS or WhatsApp.
   * Read `ownership.next` for what advances it, and re-read later if
   * `ownership` is momentarily `null`.
   * - `released` means this number is no longer allocated to your workspace.
   *
   * An allocated number is not always enough to send from it: some destination
   * countries also require an approved registration for the sender.
   *
   */
  readonly status: "active" | "pending_ownership_registration" | "released";
  /**
   * When this number was allocated to your workspace.
   */
  readonly allocated_at: string;
  /**
   * When this number was released. `null` while it is still allocated to your workspace.
   */
  readonly released_at?: string | null;
  /**
   * Where this number stands with the ownership paperwork its country requires. `null` when the country requires none, which is the usual case: a number with no `ownership` object is usable as soon as it is allocated. Also `null` when that standing cannot be established right now; `status` still reads `pending_ownership_registration` while the number is blocked, so re-read this field rather than caching its absence. We manage the paperwork for shared short codes, so this field is always `null` for them.
   *
   */
  readonly ownership?: NumberOwnership | null;
};

export type NumberList = {
  data: Array<Number>;
} & ListEnvelope;

export type AvailableNumber = {
  /**
   * Phone number in E.164 format.
   */
  number: string;
  country_code: CountryCode;
  /**
   * Physical type of this phone number.
   */
  number_type: NumberType;
  /**
   * Capabilities supported by this number.
   */
  capabilities: Array<NumberCapability>;
  /**
   * Whether ownership paperwork must be approved before outbound SMS and voice use. Customer availability accounts for organization exemptions; admin supplier searches report the general country and number-type requirement. You can acquire the number, including Bird stock, and submit paperwork afterward. Any setup fee is charged during purchase. Monthly billing starts at assignment even while approval is pending; assignment may follow completion of a pending supplier order.
   */
  ownership_registration_required: boolean;
};

export type AvailableNumberList = {
  data: Array<AvailableNumber>;
} & ListEnvelope;

/**
 * Lifecycle state of a number purchase order:
 *
 * - `charging`: Securing funds.
 * - `ordering`: Placing the order with the carrier.
 * - `pending`: The carrier accepted the order and is provisioning the number.
 * - `completed`: Your workspace owns the number.
 * - `failed`: The purchase did not complete.
 *
 * A setup fee already charged is non-refundable. Contact support about a failed
 * order.
 */
export type NumbersOrderStatus =
  "charging" | "ordering" | "pending" | "completed" | "failed" | (string & {});

export type NumbersOrderId = string;

export type NumbersOrder = {
  /**
   * Identifier of this purchase order.
   */
  readonly id: NumbersOrderId;
  /**
   * The number being acquired, in E.164 format.
   */
  readonly number: string;
  readonly country_code: CountryCode;
  /**
   * Physical type of the number being acquired.
   */
  readonly number_type: NumberType;
  readonly status: NumbersOrderStatus;
  /**
   * Identifier of the number this order produced, set when `status` is `completed`. Pass it as `number_id` to `GET /v1/numbers/{number_id}` or `DELETE /v1/numbers/{number_id}`. `null` until the order completes.
   *
   */
  readonly number_id?: NumbersDedicatedAllocationId | null;
  /**
   * Human-readable reason the purchase failed. `null` unless status is failed. An order can fail some time after it was created, so `updated_at` tells you when the failure was recorded rather than when the order was placed.
   *
   */
  readonly failure_reason?: string | null;
  /**
   * When the purchase completed and the number became owned (status completed). `null` for orders still in progress or failed.
   *
   */
  readonly completed_at?: string | null;
  readonly created_at: string;
  readonly updated_at: string;
};

export type NumbersOrderList = {
  data: Array<NumbersOrder>;
} & ListEnvelope;

export type NumbersOrderCreate = {
  /**
   * The number to acquire, in E.164 format, as returned by `GET /v1/numbers/available`.
   */
  number: string;
};

export type SipTrunkId = string;

/**
 * Which answer a number carries.
 *
 * - `reject`: refuses the call. This is where every number starts.
 * - `trunk`: delivers the call to one of your SIP trunks.
 * - `forward`: places a call to one of your verified caller IDs and connects the two.
 *
 * It selects the answer's own shape, so a new way to answer a call arrives as a
 * new value alongside a new set of fields.
 *
 */
export type VoiceCallRouteType = "reject" | "trunk" | "forward";

/**
 * Which of a forwarded call's two numbers it shows as the caller.
 *
 * "dialed_number" is the number the caller dialled, which is one of yours.
 * Carriers treat it as fully yours, so it is the least likely to be altered or
 * screened. Whoever answers sees which of your numbers was called, not who called
 * it. It needs your workspace approved to place calls from numbers you bought from
 * us; where it is not, this value is refused and the call shows the calling
 * number.
 *
 * "calling_number" is the caller's own number, so the phone rings as though they
 * had dialled it directly and the call can be returned from the call log. Because
 * the number is not one you own, some carriers (most often in the US and parts of
 * Europe) mark such calls as unverified, replace the number, or screen them.
 *
 */
export type VoiceInboundForwardAs = "dialed_number" | "calling_number";

/**
 * Why we rejected the call. Use `rejection_reason` to identify the cause;
 * `sip_response_code` alone cannot distinguish these reasons.
 *
 * You can resolve these issues:
 *
 * - `source_not_allowed`: The call came from an IP address that is not in the
 * trunk's allowed-address list. Add the address your PBX sends from.
 * - `caller_id_not_verified`: The number in the `From` header is not a verified
 * caller ID for this workspace. Verify it or use a verified caller ID.
 * - `number_ownership_not_verified`: The ownership documents for this purchased
 * number have not yet been accepted under its country's requirements. We
 * block outgoing and incoming calls on the number until verification is
 * complete. Blocked incoming calls never reach your PBX, and their route type
 * is `reject` regardless of the number's configuration. Open the number
 * under **Numbers** and complete its ownership requirements, then retry
 * the call.
 * - `destination_not_enabled`: Calling to this destination country is disabled.
 * Enable it in your voice destination settings.
 * - `insufficient_balance`: Your wallet balance was too low for the call.
 * Top up or enable automatic top-ups.
 * - `daily_spend_exceeded`: The call would exceed your organization's daily
 * voice spend limit. Retry after the limit resets at the start of the next
 * UTC day.
 * - `concurrent_calls_exceeded`: You already have as many calls in progress as
 * your account allows. Wait for one to end or ask support to raise the limit.
 * - `calls_per_second_exceeded`: You placed calls faster than your account
 * allows. Reduce your dialing rate and retry.
 *
 * For all other reasons, contact support and provide the call `id`:
 *
 * - `routing_not_configured`: This trunk has no dial plan, which can happen on
 * a new trunk.
 * - `no_route_found`: A dial plan is attached, but no rule in it covers this
 * destination.
 * - `destination_blocked`: The destination is blocked by our routing
 * configuration.
 * - `call_not_permitted`: The call could not be priced for your account.
 *
 */
export type VoiceCallRejectionReason =
  | "source_not_allowed"
  | "caller_id_not_verified"
  | "routing_not_configured"
  | "no_route_found"
  | "destination_blocked"
  | "destination_not_enabled"
  | "insufficient_balance"
  | "daily_spend_exceeded"
  | "concurrent_calls_exceeded"
  | "calls_per_second_exceeded"
  | "call_not_permitted"
  | "number_ownership_not_verified";

export type VoiceCallInboundRouteReject = {
  /**
   * The number turned the call away. This is where every number starts, so it covers a number nobody has configured as well as one set to reject.
   *
   */
  type: VoiceCallRouteType;
};

export type VoiceCallInboundRouteTrunk = {
  /**
   * The call was delivered to one of your SIP trunks.
   */
  type: VoiceCallRouteType;
  /**
   * The SIP trunk the call was delivered to. Recorded as it was at the time, so it may name a trunk you have since changed or deleted.
   *
   */
  trunk_id: SipTrunkId;
};

export type VoiceCallInboundRouteForward = {
  /**
   * The call was forwarded to another of your numbers.
   */
  type: VoiceCallRouteType;
  /**
   * The number the call was forwarded to, in E.164 format. Recorded as it was at the time, so it may name a number you have since stopped verifying.
   *
   */
  forward_to: string;
  /**
   * Which of the call's two numbers the forwarded leg presented as its caller. The value that went on the wire, not the one the number is set to now.
   *
   */
  forward_as: VoiceInboundForwardAs;
};

/**
 * The routing choice recorded for an incoming call. A recorded route does not
 * guarantee that the call connected. Check `status` for the outcome and
 * `rejection_reason` for the cause when present.
 *
 */
export type VoiceCallInboundRoute =
  | ({
      type: "reject";
    } & VoiceCallInboundRouteReject)
  | ({
      type: "trunk";
    } & VoiceCallInboundRouteTrunk)
  | ({
      type: "forward";
    } & VoiceCallInboundRouteForward);

export type VoiceMediaQuality = {
  /**
   * Mean opinion score, the single number for how the call sounded, from 1 (unintelligible) to 5 (as good as being in the same room). Anything at or above 4.0 is what most people would call a clear line, and below 3.5 is where callers start asking each other to repeat themselves. The three other fields are the impairments that move it.
   *
   */
  readonly mos: number;
  /**
   * Variation in the arrival time of the audio packets, in milliseconds. Audio arriving unevenly is heard as choppiness even when no packets are lost at all.
   */
  readonly jitter_ms: number;
  /**
   * Percentage of audio packets that never arrived. Heard as brief gaps or clipped words, and the impairment that degrades a call fastest.
   */
  readonly packet_loss_pct: number;
  /**
   * Round-trip time between the two ends, in milliseconds. It does not distort the audio. Above roughly 300 ms, the two parties start talking over each other.
   */
  readonly round_trip_time_ms: number;
};

/**
 * What was charged for a call, split into the components that make it up.
 *
 */
export type VoiceCallCost = {
  /**
   * Total charged, as a decimal string: the sum of the components below. Net of tax, which applies to your wallet balance rather than to an individual charge.
   *
   */
  readonly amount: string;
  /**
   * ISO 4217 currency code. Every component is denominated in this currency.
   */
  readonly currency_code: CurrencyCode;
  /**
   * What we charged to carry the call to the destination network, as a decimal string. `null` until this component is priced.
   *
   */
  readonly outbound_amount: string | null;
  /**
   * What we charged to receive the call from the originating network, as a decimal string. Only a call that arrived at your number can carry it. `null` until this component is priced.
   *
   */
  readonly inbound_amount: string | null;
  /**
   * What we charged for handling the call itself, as a decimal string. A call is charged for handling once, however many legs it has, so only one leg's record carries it. `null` until this component is priced.
   *
   */
  readonly call_handling_amount: string | null;
  /**
   * What we charged to record the call, as a decimal string, billed per second over the same billable time as the rest of the call. `null` until this component is priced.
   *
   */
  readonly recording_amount: string | null;
  /**
   * What we charged to transcribe the call's audio, as a decimal string, billed per second of recorded audio rather than for the length of the call. A transcript is produced after the call ends, so this can appear after the rest of the cost. `null` until this component is priced.
   *
   */
  readonly transcription_amount: string | null;
};

export type VoiceCall = {
  /**
   * Unique identifier for this call record.
   */
  readonly id: VoiceCallId;
  /**
   * Session identifier shared across all legs of a multi-party or transferred call. Use this to correlate related call records. `null` when session correlation is not available for the call.
   */
  readonly session_id?: VoiceSessionId | null;
  readonly workspace_id: WorkspaceId;
  readonly direction: VoiceCallDirection;
  /**
   * Calling party number in E.164 format.
   */
  readonly from: string;
  /**
   * Called party number in E.164 format.
   */
  readonly to: string;
  /**
   * Who placed the call: the API key whose credentials it used, the integration acting for the workspace, or the user who placed it from a browser or the CLI. Absent when the call was admitted only by its source IP address, or when no actor was recorded.
   */
  readonly actor?: Actor;
  /**
   * Identifier of the SIP trunk that originated this call. `null` when no trunk is associated.
   */
  readonly sip_trunk_id?: SipTrunkId | null;
  readonly status: VoiceCallStatus;
  /**
   * Final SIP response code received from the carrier. `null` when no SIP response was received, for example on timeout or DNS failure.
   */
  readonly sip_response_code?: number | null;
  /**
   * Why we rejected the call. Absent on connected calls and calls rejected
   * by the carrier or recipient. For carrier or recipient rejections, see
   * `sip_response_code`; a `6xx` decline gives the call a `rejected` status.
   *
   * Read alongside `route` when present. A refusal caused by the number's
   * configuration has no rejection reason; the route records that
   * configuration.
   *
   */
  readonly rejection_reason?: VoiceCallRejectionReason;
  /**
   * Which answer your number gave an incoming call: a SIP trunk, a forward, or a refusal. Recorded when the call was handled, so changing the number's setup afterwards does not change what its past calls say. Absent on outbound calls, and on calls recorded before this field existed.
   */
  readonly route?: VoiceCallInboundRoute;
  /**
   * Your own `{name, value}` labels for this call, taken from the `X-Bird-Call-Tag` headers on the INVITE that placed it. Set them to organise calls by a dimension of your own (campaign, queue, agent, cost centre), then filter this list by them with `tag`. Read-only here: a call is labelled when it is placed, and never afterwards. What is here may be less than what was sent, and the call still goes through either way: a tag whose name or value breaks the rules below is dropped, anything past the first five is ignored, and a name sent more than once keeps its first value. Absent when the call carried none, and on calls recorded before this field existed.
   */
  readonly tags?: Array<Tag>;
  /**
   * When the call was initiated.
   */
  readonly started_at: string;
  /**
   * When the call was answered (`200` OK received). `null` for unanswered calls.
   */
  readonly answered_at?: string | null;
  /**
   * When the call ended (BYE or final non-2xx response). `null` for calls that ended abnormally without a recorded end event.
   */
  readonly ended_at?: string | null;
  /**
   * Total call duration in milliseconds, measured from the first INVITE to the BYE or final response. `null` while the call is still in progress and has no final duration yet.
   */
  readonly duration_ms?: number | null;
  /**
   * Post-dial delay in milliseconds: how long the caller heard nothing between dialing and the phone starting to ring at the other end. High values are what callers experience as the call `not going through`. Absent when the call never rang, either because it failed first or because the carrier answered it immediately.
   *
   */
  readonly pdd_ms?: number;
  /**
   * Billable duration in milliseconds, measured from answer to call end. Zero for unanswered calls, and `null` while the call is still in progress.
   */
  readonly billable_ms?: number | null;
  /**
   * How the audio sounded, as opposed to whether the call connected. Absent when the call carried no audio, or when the far end reported nothing to measure from.
   */
  media_quality?: VoiceMediaQuality;
  /**
   * What the call cost, net of tax, at full precision, split into the components that make it up. Absent until the call has been rated; unanswered or unpriced calls have no cost.
   */
  cost?: VoiceCallCost;
};

export type VoiceCallList = {
  data: Array<VoiceCall>;
} & ListEnvelope;

